// ─── CHRONOS IMPERIUM · Curated theatres ─────────────────────────────────────
// Each theatre is a set of REAL states from one year of the historical-
// basemaps dataset — mutually non-overlapping by construction, so the
// strategic map reads like an atlas plate instead of stacked thematic layers.
// Every province carries a catalog nameKey (localized in imperiumCatalog) and
// an anchor: the historical capital, used as the army muster point so a
// continent-spanning empire's armies stand at its seat of power, not at the
// geometric centroid of Siberia.
//
// Regenerate geometry with scratchpad/gen-theatres.mjs.

export interface TheatreProvince {
  id: string;
  nameKey: string;                 // imperiumCatalog key — localization contract
  anchor: [number, number];        // [lat, lng] — historical capital
  rings: [number, number][][];     // dataset polygons ([lat, lng] closed rings)
}

export type TheatreId = 'successors' | 'crusades' | 'age-of-kings' | 'napoleonic';

export interface TheatreSpec {
  id: TheatreId;
  /** Which era's card the theatre appears under. */
  era: 'ancient' | 'medieval' | 'early-modern' | 'modern';
  nameKey: string;
  taglineKey: string;
  year: string;                    // display: dataset year of the map
  playerFactionKey: string;
  rivalFactionKey: string;
  playerProvinces: string[];       // starting ownership (first entry = capital)
  rivalProvinces: string[];
  /** Map camera frame [ [southLat, westLng], [northLat, eastLng] ]. */
  viewBounds: [[number, number], [number, number]];
}

